#!/usr/bin/env python3
"""Offline checks for the canonical shared-core generator; writes no artifacts.

--reference-dir optionally compares generated bytes with frozen reviewed outputs.
It is test input only and is never consulted by the production generator.
"""
from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
from pathlib import Path
import socket
import sys
import unittest
from unittest.mock import patch

sys.dont_write_bytecode = True


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo-root", type=Path, default=Path(__file__).resolve().parents[4])
    parser.add_argument("--reference-dir", type=Path)
    args = parser.parse_args(argv)
    root = args.repo_root.resolve()
    script = root / "tools/dot-auto-controller/fixed-host/scripts/build-shared-cores.py"
    spec = importlib.util.spec_from_file_location("fixed_shared_core_generator", script)
    generator = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(generator)
    gate = root / "tools/dot-auto-controller/connector-gate"
    pipe = (gate / "functions-bundle.js").read_bytes()
    observer = (gate / "dispatch-observer.functions.js").read_bytes()
    baseline = generator.render_shared_cores(pipe, observer)
    reference = None if args.reference_dir is None else {
        name: (args.reference_dir / name).read_bytes() for name in generator.OUTPUT_SHA256
    }
    check_count = 0

    class SharedCoreGenerationTests(unittest.TestCase):
        def setUp(self):
            nonlocal check_count
            check_count += 1

        def test_exact_output_hashes(self):
            self.assertEqual(set(baseline), set(generator.OUTPUT_SHA256))
            for name, source in baseline.items():
                self.assertIsInstance(source, str)
                self.assertEqual(hashlib.sha256(source.encode("utf-8")).hexdigest(), generator.OUTPUT_SHA256[name])

        def test_frozen_reference_byte_equality(self):
            if reference is None:
                self.skipTest("No optional frozen reference directory supplied")
            for name, raw in reference.items():
                self.assertEqual(baseline[name].encode("utf-8"), raw, name)

        def test_bytes_text_and_repeated_calls_are_identical(self):
            self.assertEqual(generator.render_shared_cores(pipe.decode(), observer.decode()), baseline)
            self.assertEqual(generator.render_shared_cores(pipe, observer), baseline)
            self.assertEqual(generator.render_shared_cores(pipe.decode(), observer), baseline)
            self.assertEqual(generator.render_shared_cores(pipe, observer.decode()), baseline)

        def test_input_pins_reject_single_byte_changes(self):
            for changed_pipe, changed_observer, name in (
                (pipe + b"\n", observer, "functions-bundle.js"),
                (pipe, observer + b"\n", "dispatch-observer.functions.js"),
                (pipe.replace(b"\n", b"\r\n"), observer, "functions-bundle.js"),
                (pipe, observer.replace(b"\n", b"\r\n"), "dispatch-observer.functions.js"),
                (b"\xff", observer, "functions-bundle.js"),
            ):
                with self.subTest(name=name):
                    with self.assertRaisesRegex(generator.SharedCoreSourceError, "SHARED_CORE_INPUT_SHA256:" + name):
                        generator.render_shared_cores(changed_pipe, changed_observer)

        def test_swapped_inputs_rejected(self):
            with self.assertRaisesRegex(generator.SharedCoreSourceError, "SHARED_CORE_INPUT_SHA256:functions-bundle.js"):
                generator.render_shared_cores(observer, pipe)

        def test_non_source_input_types_rejected(self):
            for value in (None, {}, bytearray(pipe)):
                with self.subTest(type=type(value).__name__):
                    with self.assertRaisesRegex(TypeError, "SHARED_CORE_SOURCE_TYPE"):
                        generator.render_shared_cores(value, observer)

        def test_transform_occurrence_guard_is_not_assert(self):
            with self.assertRaisesRegex(generator.SharedCoreSourceError, "SHARED_CORE_TRANSFORM_COUNT:1:2"):
                generator._replace_exact("aa", "a", "b")
            with self.assertRaisesRegex(generator.SharedCoreSourceError, "SHARED_CORE_TRANSFORM_COUNT:1:0"):
                generator._replace_exact("a", "z", "b")
            self.assertEqual(generator._replace_exact("aa", "a", "b", count=2), "bb")

        def test_export_suffix_guard(self):
            with self.assertRaisesRegex(generator.SharedCoreSourceError, "SHARED_CORE_EXPORT_SUFFIX"):
                generator._remove_suffix("prefix suffix extra", "suffix")

        def test_pure_function_performs_no_filesystem_or_network_io(self):
            failure = AssertionError("RENDER_ATTEMPTED_EXTERNAL_IO")
            with patch("builtins.open", side_effect=failure), patch.object(Path, "open", side_effect=failure), patch.object(socket, "socket", side_effect=failure), patch.object(socket, "create_connection", side_effect=failure):
                self.assertEqual(generator.render_shared_cores(pipe, observer), baseline)

        def test_result_mutation_does_not_persist(self):
            changed = generator.render_shared_cores(pipe, observer)
            changed["pipe-core.functions.js"] = "caller change"
            self.assertEqual(generator.render_shared_cores(pipe, observer), baseline)

        def test_output_guard_rejects_incorrect_transform_result(self):
            with patch.object(generator, "_render_pipe", return_value="wrong output"):
                with self.assertRaisesRegex(generator.SharedCoreSourceError, "SHARED_CORE_OUTPUT_SHA256:pipe-core.functions.js"):
                    generator.render_shared_cores(pipe, observer)

        def test_input_guard_runs_before_transform(self):
            with patch.object(generator, "_render_pipe", side_effect=AssertionError("TRANSFORM_BEFORE_BOTH_INPUT_CHECKS")):
                with self.assertRaisesRegex(generator.SharedCoreSourceError, "SHARED_CORE_INPUT_SHA256:dispatch-observer.functions.js"):
                    generator.render_shared_cores(pipe, observer + b" ")

    suite = unittest.defaultTestLoader.loadTestsFromTestCase(SharedCoreGenerationTests)
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    report = {
        "kind": "CANONICAL_SHARED_CORE_OFFLINE_PYTHON_CHECK",
        "passed": result.wasSuccessful(),
        "testsRun": result.testsRun,
        "failures": len(result.failures),
        "errors": len(result.errors),
        "skipped": len(result.skipped),
        "frozenReferenceByteEqual": reference is not None and all(baseline[name].encode("utf-8") == raw for name, raw in reference.items()),
        "generatorSha256": hashlib.sha256(script.read_bytes()).hexdigest(),
        "testSha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        "inputSha256": {"functions-bundle.js": hashlib.sha256(pipe).hexdigest(), "dispatch-observer.functions.js": hashlib.sha256(observer).hexdigest()},
        "outputSha256": {name: hashlib.sha256(source.encode("utf-8")).hexdigest() for name, source in baseline.items()},
        "runtimeFilesWritten": 0,
        "networkCalls": 0,
    }
    print(json.dumps(report, sort_keys=True))
    return 0 if result.wasSuccessful() else 1


if __name__ == "__main__":
    raise SystemExit(main())
